const base=window.PHONE_PROFILE,storageKey=`phone-${base.key}-v4`;let stored={};try{stored=JSON.parse(localStorage.getItem(storageKey)||'{}')}catch{};if(stored&&typeof stored==='object'&&stored.wallpaperRevision!==base.wallpaperRevision&&!String(stored.wallImage||'').startsWith('data:'))delete stored.wallImage;let userFields=['wall','wallImage','userPhotos','photoFavorites','popItems','popDraft','popMessages','discordName','riotId','clockCities','alarms','weatherCity','savedVideos','streamFavorites','discordLocal','smsDrafts','notifications','smsLocal','kakaoLocal','contactFavorites','gptDrafts','kakaoDrafts','smsConversationDrafts','recLikes','blockedKakao','kakaoRevision','finalScopeRevision','savedPlaces'];let data=Object.assign({},base,Object.fromEntries(Object.entries(stored&&typeof stored==='object'&&!Array.isArray(stored)?stored:{}).filter(([key])=>userFields.includes(key)))),state={locked:true,app:null,sub:null,playing:false};
const icons=[['riot','<svg viewBox="0 0 40 40" aria-hidden="true"><path fill="currentColor" d="M7 12 29 6 35 10 32 29 28 30 28 15 25 16 25 31 21 32 21 17 18 18 18 32 14 31 14 19 11 20 12 30 8 28ZM16 34 32 32 31 36 16 37Z"/></svg>','Riot Mobile'],['rank','OP.GG','OP.GG'],['discord','<svg viewBox="0 0 40 40"><path fill="currentColor" d="M10 10Q20 6 30 10L35 28Q31 32 27 32L25 29Q20 31 15 29L13 32Q8 32 5 28Z"/><ellipse cx="15" cy="21" rx="3" ry="4" fill="#5865f2"/><ellipse cx="25" cy="21" rx="3" ry="4" fill="#5865f2"/></svg>','Discord'],['spotify','<svg viewBox="0 0 40 40"><circle cx="20" cy="20" r="18" fill="#151515"/><g fill="none" stroke="#1ed760" stroke-width="3" stroke-linecap="round"><path d="M10 15Q20 10 31 16M12 22Q21 18 29 23M14 28Q21 25 27 29"/></g></svg>','Spotify'],['pop','<svg viewBox="0 0 42 48"><path d="M10 5h12v27H10zM10 32Q15 19 25 20C42 21 41 45 24 45V15H10" fill="none" stroke="currentColor" stroke-width="3.5"/></svg>','b.stage'],['xapp','𝕏','X'],['photos','✿','사진'],['notes','▤','메모'],['instagram','◎','Instagram'],['calendar','21','일정'],['youtube','<svg viewBox="0 0 48 34"><rect x="1" y="1" width="46" height="32" rx="9" fill="#ff0033"/><path d="m20 10 14 7-14 7Z" fill="white"/></svg>','YouTube'],['clock','<svg viewBox="0 0 52 52"><circle cx="26" cy="26" r="23" fill="white"/><g stroke="#111" stroke-width="2.5" stroke-linecap="round"><path d="M26 26V11M26 26l11 6"/></g><path d="M26 6v20l-9 11" fill="none" stroke="#ff9500" stroke-width="1.2"/></svg>','시계'],['soop','S<i>∞</i>P','SOOP'],['chzzk','ϟ','치지직'],['weather','☀','날씨']];
for(const [id,label] of [['telephone','전화'],['messages','메시지'],['camera','카메라'],['safari','Safari']]){const found=icons.find(x=>x[0]===id);if(found)found[1]=nativePhoneSvg[id];else icons.push([id,nativePhoneSvg[id],label])}
applyAuthenticIcons();initFinalScope();initSocialReference();
const esc=(s='')=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),dateKey=(date=new Date())=>date.toLocaleDateString('sv-SE',{timeZone:'Asia/Seoul'}),now=()=>new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',hour12:false,timeZone:'Asia/Seoul'}),today=()=>new Date().toLocaleDateString('ko-KR',{month:'long',day:'numeric',weekday:'long',timeZone:'Asia/Seoul'});function save(){try{localStorage.setItem(storageKey,JSON.stringify(data))}catch{toast('이 브라우저에서는 저장할 수 없습니다')}}function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>e.classList.remove('show'),1800)}
function homeIcon(id,label=true){const item=icons.find(x=>x[0]===id);return item?`<button class="appbtn" data-open="${id}" aria-label="${item[2]}"><span class="appicon ${id}">${item[1]}</span>${label?item[2]:''}</button>`:''}
function home(){return fixedHome()}
function bindHomePages(){const pages=document.querySelector('#homePages');if(!pages)return;const width=pages.clientWidth;if(width>0)pages.scrollLeft=(state.homePage??1)*width;let settle;pages.addEventListener('scroll',()=>{clearTimeout(settle);settle=setTimeout(()=>{if(pages.isConnected===false||!pages.clientWidth)return;state.homePage=Math.max(0,Math.min(2,Math.round(pages.scrollLeft/pages.clientWidth)));pages.dataset.page=state.homePage},90)},{passive:true});let startX,startLeft,dragging=false;pages.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0||e.target.closest('button,input,a'))return;startX=e.clientX;startLeft=pages.scrollLeft;dragging=true;pages.style.scrollSnapType='none';pages.setPointerCapture(e.pointerId)});pages.addEventListener('pointermove',e=>{if(dragging)pages.scrollLeft=startLeft-(e.clientX-startX)});const endDrag=()=>{if(!dragging)return;dragging=false;pages.style.scrollSnapType='';const page=Math.max(0,Math.min(2,Math.round(pages.scrollLeft/pages.clientWidth)));pages.scrollTo({left:page*pages.clientWidth,behavior:'smooth'})};pages.addEventListener('pointerup',endDrag);pages.addEventListener('pointercancel',endDrag);const input=document.querySelector('#librarySearch'),categories=document.querySelector('#libraryCategories'),results=document.querySelector('#libraryResults'),cancel=document.querySelector('#libraryCancel');const search=()=>{const q=input.value.trim().toLocaleLowerCase();categories.hidden=true;results.hidden=false;let count=0;document.querySelectorAll('[data-library-name]').forEach(row=>{row.hidden=!row.dataset.libraryName.includes(q);if(!row.hidden)count++});const empty=document.querySelector('#libraryNoResults');if(empty)empty.hidden=count>0;pages.classList.add('library-searching')};input?.addEventListener('focus',search);input?.addEventListener('input',search);cancel?.addEventListener('click',()=>{input.value='';input.blur();categories.hidden=false;results.hidden=true;pages.classList.remove('library-searching')})}

function shell(title,body){return `<section class="appview"><header class="apphead"><button class="backbtn">‹</button><div><h3>${title}</h3><p>${esc(data.name)}의 iPhone</p></div></header><div class="appbody">${body}</div></section>`}function chat(rows,label){return `<p class="chat-label">${esc(label)}</p><div class="chat">${rows.map(([who,msg])=>`<div class="bubble ${who==='me'?'me':''}">${esc(msg)}</div>`).join('')}</div>`}
const riotPersonIcon=`<svg viewBox="0 0 40 40" aria-hidden="true"><rect x="14" y="8" width="12" height="13" rx="4" fill="currentColor"/><path d="M11 25Q20 21 29 25L32 33Q20 38 8 33Z" fill="currentColor"/></svg>`;
const riotFist=`<svg viewBox="0 0 40 40" aria-hidden="true"><path fill="currentColor" d="M7 12 29 6 35 10 32 29 28 30 28 15 25 16 25 31 21 32 21 17 18 18 18 32 14 31 14 19 11 20 12 30 8 28Z"/><path fill="currentColor" d="m16 34 16-2-1 4-15 1Z"/></svg>`;
function riot(){
 const friendIndex=state.riotFriend||0,peer=data.riotFriends[friendIndex],isCounterpart=friendIndex===0;
 const bottom=`<nav class="riot-bottom" aria-label="Riot Mobile 탐색">${[['news','▤','소식'],['esports','♜','e스포츠'],['community','◧','커뮤니티'],['info','●','정보']].map(([id,icon,label])=>`<button data-riot-page="${id}" class="${(state.riotPage||'community')===id?'active':''}"><span>${icon}</span>${label}</button>`).join('')}</nav>`;
 if(state.sub==='riotChat'){
  const threads=(data.riotThreads||{})[friendIndex]||[],rows=isCounterpart?data.riotChat:[],local=(state.riotMessages||{})[friendIndex]||[];
  return `<section class="appview riot-view riot-chat-view"><header class="riot-chat-head"><button class="riot-round backbtn" aria-label="친구 목록으로">‹</button><span class="riot-avatar">${riotPersonIcon}<i></i></span><div><h3>${esc(peer)}</h3><p>${data.friendPresence?.[friendIndex]==='playing'?'리그 오브 레전드 · 게임 중':data.friendPresence?.[friendIndex]==='away'?'자리 비움':'온라인'}</p></div><button class="riot-round riot-more" aria-label="대화 정보">•••</button></header><div class="riot-conversation"><p class="riot-safety">라이엇 직원은 고객 지원 시 절대로 이용자의<br>비밀번호를 묻지 않습니다.</p>${isCounterpart||threads.length?'':'<p class="riot-date">아직 대화가 없습니다.</p>'}<div class="chat">${rows.map(([who,msg])=>`<div class="bubble ${who==='me'?'me':''}">${esc(msg)}</div>`).join('')}${threads.map(t=>`<p class="riot-date riot-session-date">${t.date?esc(t.date):'• • •'}</p>${t.rows.map(([who,msg])=>`<div class="bubble ${who==='me'?'me':''}">${esc(msg)}</div>`).join('')}`).join('')}${local.map(msg=>`<div class="bubble me">${esc(msg)}</div>`).join('')}</div></div><form id="riotComposer" class="riot-composer"><input id="riotMessage" placeholder="메시지 전송" maxlength="500" autocomplete="off" aria-label="메시지"><button aria-label="메시지 표시">➤</button></form></section>`;
 }
 const page=state.riotPage||'community',tab=state.riotTab||'friends';
 let body='';
 if(page==='community'){
  body=`<header class="riot-community-head"><button class="backbtn riot-exit" aria-label="홈으로">‹</button><h2>커뮤니티</h2><button class="riot-round riot-more" aria-label="앱 정보">•••</button></header><div class="riot-tabs" role="tablist">${[['friends','친구'],['messages','메시지'],['requests','요청']].map(([id,label])=>`<button role="tab" aria-selected="${tab===id}" data-riot-tab="${id}" class="${tab===id?'selected':''}">${label}</button>`).join('')}</div><div class="riot-community-scroll">`;
  if(tab==='requests')body+=`<div class="riot-empty">친구 요청이 없습니다.</div>`;
  else{
   body+=`<label class="riot-search"><span>⌕</span><input id="riotSearch" placeholder="검색" aria-label="친구 검색"></label><p class="riot-group">${tab==='messages'?'메시지':'친구'} <span>${tab==='messages'?new Set([0,...Object.keys(data.riotThreads||{}).map(Number)]).size:data.riotFriends.length}</span></p>`;
   body+=data.riotFriends.map((f,i)=>tab==='messages'&&i!==0&&!(data.riotThreads||{})[i]?.length?'':`<button class="riot-friend" data-riot-friend="${i}" data-search="${esc(f.toLowerCase())}"><span class="riot-avatar game-${data.friendPresence?.[i]||'online'}">${riotPersonIcon}<i></i></span><span class="riot-friend-text"><strong>${esc(f)}</strong><small class="${data.friendPresence?.[i]==='playing'?'playing-text':''}">${tab==='messages'?'대화 보기':data.friendPresence?.[i]==='playing'?'리그 오브 레전드 · 게임 중':data.friendPresence?.[i]==='away'?'자리 비움':'온라인'}</small></span></button>`).join('');
   body+=`<p id="riotNoResults" class="riot-data-note" hidden>검색 결과가 없습니다.</p>`;
  }
  body+='</div>';
 }else{
  if(page==='info')return riotInfo(bottom);if(page==='news'||page==='esports')return riotFeed(page,bottom);
  const titles={news:'소식',esports:'e스포츠',info:'정보'};
  body=`<header class="riot-community-head"><button class="backbtn riot-exit" aria-label="홈으로">‹</button><h2>${titles[page]}</h2></header><div class="riot-community-scroll"><div class="riot-empty">${page==='info'?`${esc(data.name)}<br>Riot Mobile`:'공개 소식을 아래에서 확인할 수 있습니다.'}</div>${page==='news'?'<a class="riot-link" href="https://www.leagueoflegends.com/ko-kr/news/" target="_blank" rel="noopener noreferrer">리그 오브 레전드 소식 ↗</a>':page==='esports'?'<a class="riot-link" href="https://lolesports.com/ko-KR" target="_blank" rel="noopener noreferrer">LoL e스포츠 ↗</a>':''}</div>`;
 }
 return `<section class="appview riot-view">${body}${bottom}</section>`;
}
function riotFeed(page,bottom){const news=page==='news';return `<section class="appview riot-view riot-feed"><header class="riot-feed-head"><button class="backbtn riot-exit" aria-label="홈">‹</button><h2>${news?'뉴스 피드':'e스포츠'}</h2><button class="riot-round feed-menu" aria-label="메뉴">${news?'▦':'•••'}</button></header>${news?`<nav class="riot-game-filters">${[['all','전체'],['lol','♜'],['2xko','2X<br>KO'],['lor','R'],['tft','◉'],['val','V']].map(([id,label])=>`<button data-feed-game="${id}" class="${(state.feedGame||'all')===id?'selected':''}">${label}</button>`).join('')}</nav><nav class="riot-feed-tabs">${[['news','새 소식'],['esports','e스포츠'],['patch','패치 노트'],['streams','스트리밍']].map(([id,label])=>`<button data-feed-tab="${id}" class="${(state.feedTab||'news')===id?'selected':''}">${label}</button>`).join('')}</nav><div class="riot-feed-scroll">${(!state.feedTab||state.feedTab==='news')&&(!state.feedGame||['all','2xko'].includes(state.feedGame))?`<a class="riot-news-hero" href="https://www.leagueoflegends.com/ko-kr/news/" target="_blank" rel="noopener noreferrer"><svg viewBox="0 432 709 886" preserveAspectRatio="xMidYMid slice" role="img" aria-label="TRUE DAMAGE"><image href="assets/riot-news-ui.jpeg" width="709" height="1536"/></svg></a>`:`<a class="riot-feed-route" href="${state.feedTab==='patch'?'https://www.leagueoflegends.com/ko-kr/news/tags/patch-notes/':state.feedTab==='esports'?'https://lolesports.com/ko-KR':'https://www.sooplive.com/station/t1esports'}" target="_blank" rel="noopener noreferrer">${state.feedTab==='patch'?'패치 노트':state.feedTab==='esports'?'LoL e스포츠':'스트리밍'} <span>↗</span></a>`}<h3>최신</h3></div>`:`<nav class="riot-league-filters">${[['worlds','♜','월드<br>챔피언십'],['msi','♙','MSI'],['first','◈','First<br>Stand'],['lck','⌁','LCK'],['cl','⌁','LCK<br>챌린저스']].map(([id,mark,label])=>`<button data-league="${id}" class="${(state.league||'worlds')===id?'selected':''}"><span>${mark}</span><b>${label}</b></button>`).join('')}</nav><nav class="riot-feed-tabs esports-tabs"><button data-match-period="next" class="${state.matchPeriod==='next'||(state.league&&state.league!=='worlds')?'selected':''}">다음 경기</button><button data-match-period="past" class="${state.matchPeriod!=='next'?'selected':''}">지난 경기</button></nav><div class="riot-feed-scroll">${state.matchPeriod==='next'||(state.league&&state.league!=='worlds')?`<a class="riot-feed-route" href="https://lolesports.com/ko-KR" target="_blank" rel="noopener noreferrer">경기 일정 <span>↗</span></a>`:`<p class="riot-match-day">월요일 · 10월 19일</p><a class="riot-match-capture" href="https://lolesports.com/ko-KR" target="_blank" rel="noopener noreferrer"><svg viewBox="48 933 1083 1015" role="img" aria-label="KC 대 MVK 플레이-인"><image href="assets/riot-esports-ui.png" width="1179" height="2556"/></svg></a>`}</div>`}${bottom}</section>`}
function bindRiot(){
 document.querySelectorAll('[data-feed-game]').forEach(b=>b.onclick=()=>{state.feedGame=b.dataset.feedGame;render()});
 document.querySelectorAll('[data-feed-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.feedTab==='esports'){state.riotPage='esports'}else state.feedTab=b.dataset.feedTab;render()});
 document.querySelectorAll('[data-league]').forEach(b=>b.onclick=()=>{state.league=b.dataset.league;if(state.league!=='worlds')state.matchPeriod='next';render()});
 document.querySelectorAll('[data-match-period]').forEach(b=>b.onclick=()=>{state.matchPeriod=b.dataset.matchPeriod;render()});

 document.querySelectorAll('[data-riot-friend]').forEach(b=>b.onclick=()=>{state.riotFriend=Number(b.dataset.riotFriend);state.sub='riotChat';render()});
 document.querySelectorAll('[data-riot-tab]').forEach(b=>b.onclick=()=>{state.riotTab=b.dataset.riotTab;render()});
 document.querySelectorAll('[data-riot-page]').forEach(b=>b.onclick=()=>{state.riotPage=b.dataset.riotPage;state.sub=null;render()});
 document.querySelector('#riotSearch')?.addEventListener('input',e=>{const q=e.target.value.trim().toLowerCase();let found=0;document.querySelectorAll('[data-search]').forEach(b=>{b.hidden=!b.dataset.search.includes(q);if(!b.hidden)found++});document.querySelector('#riotNoResults').hidden=found>0});
 document.querySelector('#riotComposer')?.addEventListener('submit',e=>{e.preventDefault();const input=document.querySelector('#riotMessage'),msg=input.value.trim();if(!msg)return;const i=state.riotFriend||0;state.riotMessages??={};state.riotMessages[i]??=[];state.riotMessages[i].push(msg);render();const scroll=document.querySelector('.riot-conversation');if(scroll)scroll.scrollTop=scroll.scrollHeight;document.querySelector('#riotMessage')?.focus()});
 document.querySelector('.riot-more')?.addEventListener('click',()=>toast(data.riotFriends[state.riotFriend||0]));
}
function nativeShell(title,body,kind='',footer=''){return `<section class="appview native ${kind}"><header class="native-head"><button class="backbtn" aria-label="뒤로">‹</button><h2>${title}</h2></header><div class="native-scroll">${body}</div>${footer}</section>`}
const outLink=(url,label,cls='native-link')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}</a>`;
function spotify(){const fav=data.favoriteTrack,selected=state.spotifyTrack||fav.id;return nativeShell('Spotify',`<div class="spotify-filters"><span class="selected">음악</span><span>내 라이브러리</span></div><div class="favorite-card"><img src="assets/favorite-cover.jpg" alt="${esc(fav.title)} 앨범 커버"><div><small>좋아하는 곡</small><h3>${esc(fav.title)}</h3><p>${esc(fav.artist)}</p><button data-track="${fav.id}" class="green-button">▶</button></div></div><iframe class="spotify-player" title="Spotify 곡 재생" src="https://open.spotify.com/embed/track/${selected}?theme=0" height="152" allow="autoplay; clipboard-write; encrypted-media; fullscreen; picture-in-picture" loading="lazy"></iframe>${outLink('https://open.spotify.com/track/'+selected,'Spotify에서 재생 ↗')}<h3 class="native-title">My Gaming Songs: ${base.key==='doran'?'Doran':'Peyz'}</h3><div class="spotify-playlist-cover"><img src="assets/spotify-cover.jpg" alt="Spotify 공개 플레이리스트 커버"><div><b>${esc(data.name)}의 플레이리스트</b><small>Spotify</small>${outLink('https://open.spotify.com/playlist/'+data.spotifyPlaylist,'Spotify에서 열기 ↗')}</div></div>${data.songs.map((x,i)=>`<button class="song-row ${selected===x.id?'selected':''}" data-track="${x.id}"><span>${i+1}</span><div><strong>${esc(x.title)}</strong><small>${esc(x.artist)}</small></div><em>${Math.floor(x.duration/60)}:${String(x.duration%60).padStart(2,'0')}</em></button>`).join('')}`,'spotify-native',`<nav class="native-bottom"><button data-spotify-home>⌂<small>홈</small></button><button data-spotify-library>▤<small>내 라이브러리</small></button></nav>`)}
function rank(){const r=data.recentStats,tab=state.rankTab||'summary';return `<section class="appview native opgg-mobile"><div class="native-scroll"><header class="opgg-art"><button class="backbtn">‹</button><a href="${data.opgg}" target="_blank" rel="noopener noreferrer" aria-label="전적 갱신">↻</a></header><section class="opgg-card"><small>Lv. <b>${data.rankLevel.toLocaleString()}</b>　 |　 래더 랭킹: <b class="blue">${data.rankPosition}th</b></small><h2>${esc(data.riotId.split('#')[0])} <span>#${esc(data.riotId.split('#')[1])}</span></h2><p><b class="pro-pill">PRO</b> <span class="t1-red">T1</span> T1 · 🇰🇷 KR</p>${imageRegion('assets/opgg-ui.jpeg',500,211,172,244,'rank-badge',data.rank+' '+data.rankLP+' LP')}</section><div class="opgg-summary"><article><b>최근 20경기 요약 정보</b><h3>${r.kda}:1</h3><p>승률 ${r.winrate}%<br>KDA ${r.kills} / <em>${r.deaths}</em> / ${r.assists}</p></article><article><small>개인/2인 랭크 게임</small><h3>${data.rank==='CHALLENGER'?'Challenger':'Grandmaster'}</h3><p>${data.rankLP.toLocaleString()} LP<br>${data.rankWins}승 ${data.rankLosses}패 (${data.rankWinrate}%)</p></article></div><nav class="opgg-tabs">${[['summary','Matches'],['most','모스트'],['mastery','숙련도']].map(([id,label])=>`<button data-rank-tab="${id}" class="${tab===id?'selected':''}">${label}</button>`).join('')}</nav>${tab==='summary'?`<div class="queue-type">⚑　큐 타입 : 전체</div>${data.recentMatches.map((x,i)=>`<article class="match-card ${x.win?'win':'loss'}"><header><b>${x.win?'승리':'패배'}</b> <span>${x.duration||''}</span><small>개인/2인 랭크 게임</small></header><div class="match-summary"><img class="match-champ" src="assets/champ-${x.champ}.png" alt="${esc(x.name)}" width="44" height="44"><div><strong>${x.kda}</strong><p>${x.name}</p></div><small>CS ${x.cs}</small></div>${x.tag?`<span class="match-tag">${x.tag}</span>`:''}</article>`).join('')}`:tab==='most'?data.most.map((x,i)=>`<div class="champ-row"><span class="most-position">${i+1}</span><img src="assets/champ-${{"제이스": "Jayce", "암베사": "Ambessa", "올라프": "Olaf", "바루스": "Varus", "이즈리얼": "Ezreal", "유나라": "Yunara", "카이사": "Kaisa", "아펠리오스": "Aphelios"}[x.name]}.png" alt="${esc(x.name)}" width="44" height="44"><div><b>${x.name}</b><small>${x.wins+x.losses}게임 · ${x.wins}승 ${x.losses}패 · ${x.rate}%</small><small>KDA ${x.kda}:1</small></div></div>`).join(''):data.champs.map(x=>`<div class="champ-row"><img src="assets/champ-${x.id}.png" alt="${x.name}"><div><b>${x.name}</b><small>레벨 ${x.level} · ${x.points.toLocaleString()} 포인트</small></div></div>`).join('')}</div></section>`}

function notes(){if(state.sub?.startsWith('note:')){const n=data.notes[Number(state.sub.split(':')[1])];return nativeShell('메모',`<article class="ios-note"><small>${esc(n.date)}</small><h2>${esc(n.title)}</h2><p>${esc(n.text).replaceAll('\n','<br>')}</p>${n.url?outLink(n.url,'빌드 확인 ↗'):''}</article>`,'notes-native')};return nativeShell('메모',`<h1 class="ios-large-title">메모</h1><div class="note-list">${data.notes.map((n,i)=>`<button data-note="${i}"><strong>${esc(n.title)}</strong><small>${esc(n.date)} ${esc(n.text.split('\n')[0])}</small><span>›</span></button>`).join('')}</div><p class="ios-count">${data.notes.length}개의 메모</p>`,'notes-native')}
function albumItems(){return [...(data.userPhotos||[]),...(data.photoAlbums||[]),...(data.petImage&&!(data.photoAlbums||[]).some(x=>x.src===data.petImage)?[{src:data.petImage,title:data.petTitle}]:[])]}
function photos(){const items=albumItems(),petOnly=state.sub==='album:pets',favorite=state.sub==='album:favorites',custom=state.sub==='album:sea'?'sea':state.sub==='album:food'?'food':null;if(state.sub?.startsWith('photo:')){const i=Number(state.sub.split(':')[1]),item=items[i];return nativeShell(esc(item.title),`<div class="photo-stage" id="photoStage"><img class="full-photo" src="${esc(item.src)}" alt="${esc(item.title)}"></div><div class="photo-navigation"><button data-photo-step="-1" aria-label="이전 사진">‹</button><span>${i+1} / ${items.length}</span><button data-photo-step="1" aria-label="다음 사진">›</button></div><div class="photo-actions"><button id="favoritePhoto" aria-pressed="${(data.photoFavorites||[]).includes(item.src)}">${(data.photoFavorites||[]).includes(item.src)?'♥':'♡'}</button><button id="useWallpaper">배경화면으로 설정</button></div>`,'photos-native')};const filtered=items.map((p,i)=>({...p,index:i})).filter(p=>petOnly?isPetPhoto(p):favorite?(data.photoFavorites||[]).includes(p.src):custom?p.album===custom:true);return nativeShell(petOnly?data.petTitle:favorite?'즐겨찾기':custom==='sea'?'🌊':custom==='food'?'🍽️':'사진',`<div class="photos-heading"><h1 class="ios-large-title">${petOnly?esc(data.petTitle):favorite?'즐겨찾기':custom==='sea'?'🌊':custom==='food'?'🍽️':'보관함'}</h1><label class="ios-add">추가<input id="photoUpload" type="file" accept="image/*" hidden multiple></label></div>${petOnly?`<p class="pet-album-names">${data.pets.map(p=>esc(p.name)).join(' · ')}</p>`:''}<div class="gallery-grid">${filtered.map(p=>`<button data-photo="${p.index}"><img src="${esc(p.src)}" alt="${esc(p.title)}" loading="lazy" decoding="async"></button>`).join('')}</div><p class="photos-total">${filtered.length}장의 사진</p>${!petOnly&&!favorite&&!custom?`<h3 class="native-title">나의 앨범</h3><div class="photo-albums"><button data-photo-album="${data.key==='doran'?'sea':'food'}"><span>${data.key==='doran'?'🌊':'🍽️'}</span><b>${data.key==='doran'?'바다':'음식'}</b><small>${items.filter(x=>x.album===(data.key==='doran'?'sea':'food')).length}장</small></button><button data-photo-album="pets"><img src="${esc(data.petImage)}" alt=""><b>${esc(data.petTitle)}</b><small>${items.filter(isPetPhoto).length}장</small></button><button data-photo-album="favorites"><span>♥</span><b>즐겨찾기</b><small>${(data.photoFavorites||[]).length}장</small></button></div>`:''}`,'photos-native',`<nav class="native-bottom"><button data-photo-album="all">▦<small>보관함</small></button><button data-photo-album="pets">▧<small>앨범</small></button></nav>`)}
function isPetPhoto(p){return p.petAlbum===true||(p.petAlbum!==false&&(p.src===data.petImage||p.title===data.petTitle))}

function discord(){return discordReference()}

const bstMark=`<svg viewBox="0 0 42 48" aria-hidden="true"><path d="M10 5h12v27H10zM10 32Q15 19 25 20C42 21 41 45 24 45V15H10" fill="none" stroke="currentColor" stroke-width="3.5"/></svg>`;
const t1Mark=`<svg viewBox="91 790 2318 920" role="img" aria-label="T1"><image href="data:image/png;base64," width="2500" height="2500"/></svg>`;
function profileAvatar(size=''){if(data.xProfileEdits?.avatar)return `<span class="profile-avatar ${data.key} ${size} custom-avatar" style="background-image:url('${data.xProfileEdits.avatar}')"></span>`;return `<span class="profile-avatar ${data.key} ${size}" role="img" aria-label="${esc(data.xProfile.name)} 프로필" style="background-image:url('${data.xProfile.avatarSheet}')"></span>`}
function popMessage(row){if(row.type==='sticker'&&row.sticker==='moved')return `<div class="pop-message pop-outgoing pop-sticker-row">${imageRegion('assets/pop-more-ui.jpeg',88,750,195,200,'pop-sprite-sticker','감동란')}<time>${esc(row.time)}</time></div>`;if(row.type==='media')return `<div class="pop-message pop-outgoing"><button class="pop-media" data-pop-media="${esc(row.media)}" aria-label="사진 확대">${popMediaImage(row.media)}</button><time>${esc(row.time)}</time></div>`;if(row.type==='date')return `<div class="pop-day" data-pop-day="${esc(row.text)}">${esc(row.text)}</div>`;if(row.type==='sticker')return `<div class="pop-message pop-outgoing pop-sticker-row">${row.col===undefined?'<span class="pop-egg-sticker" role="img" aria-label="스티커"></span>':stickerImage(row.col,row.row)}</div>`;const outgoing=row.side!=='in';return `<div class="pop-message ${outgoing?'pop-outgoing':'pop-incoming'}">${!outgoing?'<small class="pop-fan-label">팬</small>':''}<div class="pop-bubble">${row.quote?`<blockquote><b>답장</b><p>${esc(row.quote)}</p></blockquote>`:''}<p>${row.quote?'↳ ':''}${esc(row.text).replaceAll('\n','<br>')}</p></div>${row.time?`<time>${esc(row.time)}</time>`:''}</div>`}
function bstageIcon(id,size=23){const paths={home:'M3 10 12 3l9 7v14h-6v-7H9v7H3Z',story:'M5 3h14v18H5ZM8 7h8M8 11h8M8 15h6',content:'M3 5h18v14H3Zm7 4 6 3-6 3Z',community:'M4 21v-3a5 5 0 0 1 10 0v3M17 15a4 4 0 0 1 4 4v2M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0Zm7 2a3 3 0 0 1-4 3',shop:'M4 7h16l1 14H3ZM8 8V6a4 4 0 0 1 8 0v2',bell:'M5 17h14l-2-3V9a5 5 0 0 0-10 0v5ZM10 21h4',calendar:'M4 5h16v16H4ZM8 2v6M16 2v6M4 10h16'};return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" style="display:inline-block;vertical-align:middle;flex-shrink:0" aria-hidden="true"><path d="${paths[id]||paths.home}" stroke="currentColor" stroke-width="1.7" fill="none" stroke-linecap="round" stroke-linejoin="round"/></svg>`}
function bstage(){const name=data.key==='doran'?'최현준임':'Peyz';if(state.sub==='popMedia')return popMediaView();if(state.sub!=='popChat'){const last=data.popHistory.filter(x=>x.text&&x.side==='out').at(-1);return `<section class="appview native bstage-native"><header class="bstage-head"><button class="backbtn" aria-label="홈">‹</button>${t1Mark}<span class="bstage-head-icons" style="display:flex;gap:17px">${[['bell','알림'],['calendar','일정'],['shop','쇼핑']].map(([id,label])=>`<a href="https://t1.bstage.in/" target="_blank" rel="noopener noreferrer" aria-label="${label}" style="color:inherit">${bstageIcon(id)}</a>`).join('')}</span></header><div class="native-scroll"><h1 class="bstage-owner">${esc(name)}</h1><p class="bstage-section-label">채팅</p><div class="bstage-chat-list"><button data-pop-chat>${profileAvatar()}<span><strong>${esc(name)} <i class="pop-verified">✓</i></strong><small>${esc(last?.text||'')}</small></span><b>›</b></button></div></div><nav class="bstage-bottom">${[['home','Home'],['story','Story'],['content','Content'],['community','Community'],['shop','Shop']].map(([icon,label])=>`<a href="https://t1.bstage.in/" target="_blank" rel="noopener noreferrer"><span>${bstageIcon(icon)}</span>${label}</a>`).join('')}<button data-pop-chat class="active"><span class="pop-nav-mark">POP</span>POP</button></nav></section>`};return `<section class="appview native pop-native pop-layout" style="--pop-wall:url('${data.popWallpaper}')"><header class="pop-chat-head"><button class="backbtn" aria-label="POP 목록">‹</button><div><h2>${esc(name)} <span>⌄</span></h2><small>나의 POP</small></div><button id="popSearchToggle" aria-label="대화 검색">⌕</button></header>${state.popSearching?popSearchPanel():''}<div class="native-scroll pop-thread">${popRows().map(popMessage).join('')}</div><form id="popComposer" class="pop-composer"><button type="button" id="popPhoto" aria-label="사진 추가">＋</button><textarea id="popMessage" rows="1" placeholder="메시지 보내기" maxlength="1000">${esc(data.popDraft||'')}</textarea><button type="button" id="popSticker" aria-label="스티커">☻</button><button aria-label="메시지 표시">↑</button></form>${state.stickerOpen?stickerPicker():''}${state.popPhotos?popPhotoPicker():''}</section>`}
const xIcons={reply:'<svg viewBox="0 0 24 24"><path d="M21 11a9 9 0 0 1-9 9H8l-5 2 1-6a9 9 0 1 1 17-5Z"/></svg>',repost:'<svg viewBox="0 0 24 24"><path d="m3 8 4-4 4 4M7 4v13h8m6-1-4 4-4-4m4 4V7H9"/></svg>',heart:'<svg viewBox="0 0 24 24"><path d="M12 21 3 12C-3 3 8-2 12 5c4-7 15-2 9 7Z"/></svg>',stats:'<svg viewBox="0 0 24 24"><path d="M4 20V11m6 9V4m6 16V8m6 12V1"/></svg>',share:'<svg viewBox="0 0 24 24"><path d="M12 17V2m-5 5 5-5 5 5M3 15v7h18v-7"/></svg>'};
function xProfileScreen(){const p={...data.xProfile,...data.xProfileEdits},tab=state.xTab||'posts',posts=(data.xPosts||[]).filter(x=>tab!=='media'||x.media);return `<section class="appview native x-native x-layout"><div class="x-layout-scroll"><div class="x-banner" ${p.banner?`style="background-image:url('${p.banner}')"`:''}><button class="backbtn x-round" aria-label="홈">‹</button><div><button id="xSearch" class="x-round" aria-label="게시물 검색">⌕</button><button id="xMore" class="x-round" aria-label="프로필 메뉴">•••</button></div></div><section class="x-profile">${profileAvatar('large')}<button id="xEdit" class="x-edit">프로필 수정</button><h2>${esc(p.name)}</h2><p class="x-handle">@${esc(p.handle)}</p>${p.bio?`<p class="x-bio">${esc(p.bio)}</p>`:''}${p.location?`<p class="x-profile-extra">♧ ${esc(p.location)}</p>`:''}${p.website?`<p class="x-profile-extra">↗ ${esc(p.website)}</p>`:''}<p class="x-joined">▢ ${esc(p.joined)}에 가입함</p><div class="x-followers"><span><b>${p.following}</b> 팔로잉</span><span><b>${p.followers.toLocaleString()}</b> 팔로워</span></div>${state.xEditing?`<form id="xEditForm"><label>이름<input id="xEditName" value="${esc(p.name)}" maxlength="50"></label><label>소개<input id="xEditBio" value="${esc(p.bio)}" maxlength="160"></label><button>저장</button></form>`:''}</section><nav class="x-tabs">${[['posts','게시물'],['replies','답글'],['media','미디어']].map(([id,label])=>`<button data-x-tab="${id}" class="${tab===id?'selected':''}">${label}</button>`).join('')}</nav>${state.xSearching?'<input id="xPostSearch" class="x-post-search" placeholder="게시물 검색" aria-label="게시물 검색">':''}<div class="x-post-list">${(tab==='replies'?[]:posts).map((post,i)=>`<article class="x-post" data-x-text="${esc(post.text.toLowerCase())}">${profileAvatar()}<div class="x-post-content"><header><strong>${esc(p.name)}</strong><span>@${esc(p.handle)} · ${esc(post.date)}</span><span class="x-small-mark">𝕏</span></header><p>${esc(post.text).replaceAll('\n','<br>')}</p>${socialMediaGrid(post,data.xPosts.indexOf(post))}<footer><button data-x-reply="${data.xPosts.indexOf(post)}" aria-label="답글">${xIcons.reply}<span>${post.comments||''}</span></button><button data-x-repost="${data.xPosts.indexOf(post)}" aria-label="재게시">${xIcons.repost}<span>${post.reposts||''}</span></button><button data-x-like aria-label="좋아요">${xIcons.heart}<span>${post.likes||''}</span></button><span>${xIcons.stats}${post.views||''}</span><button data-x-share="${esc(post.url||'https://x.com/'+p.handle)}" aria-label="공유">${xIcons.share}</button></footer>${state.xReply===data.xPosts.indexOf(post)?'<form class="x-reply-form"><input placeholder="답글 게시하기" maxlength="500"><button>답글</button></form>':''}${(data.xReplies||{})[data.xPosts.indexOf(post)]?`<div class="x-local-replies">${data.xReplies[data.xPosts.indexOf(post)].map(x=>`<p>${esc(x)}</p>`).join('')}</div>`:''}</div></article>`).join('')}</div></div><button id="xCompose" class="x-compose" aria-label="게시물 작성">＋</button><nav class="x-bottom"><button id="xHome" aria-label="홈">⌂</button><button id="xSearchBottom" aria-label="검색">⌕</button><a href="https://x.com/${esc(p.handle)}" target="_blank" rel="noopener noreferrer" aria-label="프로필 열기">𝕏</a><button id="xNotifications" aria-label="알림">♧</button><button id="xMessages" aria-label="쪽지">▢</button></nav>${state.xCompose?`<div class="x-composer-overlay"><header><button id="xComposeClose">취소</button><button id="xDrafts" type="button">임시 보관함</button><button form="xComposeForm" type="submit" class="x-publish">게시하기</button></header><form id="xComposeForm"><div class="x-compose-row">${profileAvatar()}<textarea id="xComposeText" placeholder="무슨 일이 일어나고 있나요?" maxlength="280"></textarea></div><p class="x-audience">◎ 모든 사람이 답글을 달 수 있습니다</p><div class="x-tools"><button type="button" id="xAddPhoto" aria-label="사진 추가">▧</button><span>GIF</span><span>▢</span><span>❞</span></div></form></div>`:''}</section>`}
function feed(kind){return kind==='pop'?bstage():xFeed()}
function bindSocialApps(){
 document.querySelector('[data-pop-chat]')?.addEventListener('click',()=>{state.sub='popChat';render()});
 document.querySelector('#popTranslate')?.addEventListener('click',()=>{state.popTranslate=!state.popTranslate;document.querySelector('#popTranslate').classList.toggle('active')});
 document.querySelector('#popSticker')?.addEventListener('click',()=>{state.stickerOpen=!state.stickerOpen;state.popPhotos=false;save();state.popToBottom=true;render()});
 document.querySelectorAll('[data-sticker]').forEach(b=>b.onclick=()=>{const [col,row]=b.dataset.sticker.split(',').map(Number);(data.popItems??=[]).push({type:'sticker',col,row});state.stickerOpen=false;save();state.popToBottom=true;render()});
 document.querySelectorAll('[data-pop-media]').forEach(b=>b.onclick=()=>{state.popMedia=b.dataset.popMedia;state.sub='popMedia';render()});
 document.querySelectorAll('[data-send-photo]').forEach(b=>b.onclick=()=>{(data.popItems??=[]).push({type:'media',media:albumItems()[Number(b.dataset.sendPhoto)].src,time:now()});state.popPhotos=false;render()});
 document.querySelectorAll('[data-x-tab]').forEach(b=>b.onclick=()=>{state.xTab=b.dataset.xTab;render()});
 const toggleSearch=()=>{state.xSearching=!state.xSearching;render();document.querySelector('#xPostSearch')?.focus()};
 document.querySelector('#xSearch')?.addEventListener('click',toggleSearch);document.querySelector('#xSearchBottom')?.addEventListener('click',toggleSearch);
 document.querySelector('#xPostSearch')?.addEventListener('input',e=>document.querySelectorAll('[data-x-text]').forEach(x=>x.hidden=!x.dataset.xText.includes(e.target.value.trim().toLowerCase())));
 document.querySelector('#xEdit')?.addEventListener('click',()=>{state.xEditing=!state.xEditing;render()});
 document.querySelector('#xEditForm')?.addEventListener('submit',e=>{e.preventDefault();data.xProfileEdits={...(data.xProfileEdits||{}),...(state.xEditDraft||{}),name:document.querySelector('#xEditName').value.trim()||data.xProfile.name,bio:document.querySelector('#xEditBio').value,location:document.querySelector('#xEditLocation').value,website:document.querySelector('#xEditWebsite').value,birthday:document.querySelector('#xEditBirthday').value};save();state.xEditing=false;state.xEditDraft=null;render()});
 document.querySelector('#xHome')?.addEventListener('click',()=>{state.xTab='posts';render();document.querySelector('.x-layout-scroll')?.scrollTo({top:0,behavior:'smooth'})});
 document.querySelectorAll('[data-x-reply]').forEach(b=>b.onclick=()=>{state.xReply=state.xReply===Number(b.dataset.xReply)?null:Number(b.dataset.xReply);render()});
 document.querySelector('.x-reply-form')?.addEventListener('submit',e=>{e.preventDefault();const input=e.target.querySelector('input'),text=input.value.trim();if(!text)return;data.xReplies??={};data.xReplies[state.xReply]??=[];data.xReplies[state.xReply].push(text);state.xReply=null;render()});
 document.querySelectorAll('[data-x-repost]').forEach(b=>b.onclick=()=>b.classList.toggle('reposted'));
 document.querySelectorAll('[data-x-share]').forEach(b=>b.onclick=()=>{const url=b.dataset.xShare||'https://x.com/'+data.xProfile.handle;if(navigator.share)navigator.share({url}).catch(()=>{});else navigator.clipboard?.writeText(url).then(()=>toast('링크를 복사했습니다')).catch(()=>{})});
 document.querySelector('#xCompose')?.addEventListener('click',()=>{state.xCompose=true;render()});document.querySelector('#xComposeClose')?.addEventListener('click',()=>{state.xDraft=document.querySelector('#xComposeText').value;state.xCompose=false;render()});
 document.querySelector('#xComposeForm')?.addEventListener('submit',e=>{e.preventDefault();const text=document.querySelector('#xComposeText').value.trim();if(!text)return;data.xPosts.unshift({text,date:today()});state.xCompose=false;state.xTab='posts';render()});
 document.querySelector('#xNotifications')?.addEventListener('click',()=>toast('새 알림이 없습니다'));
 document.querySelector('#xMessages')?.addEventListener('click',()=>toast('쪽지가 없습니다'));
 document.querySelector('#xMore')?.addEventListener('click',()=>{state.xEditing=!state.xEditing;render()});
}
function calendar(){const date=state.calendarDate||dateKey(),month=date.slice(0,7),[y,m]=month.split('-').map(Number),offset=(new Date(y,m-1,1).getDay()+6)%7,total=new Date(y,m,0).getDate();return nativeShell('캘린더',`<div class="calendar-heading"><button data-month="-1" aria-label="이전 달">‹</button><h1>${y}년 ${m}월</h1><button data-month="1" aria-label="다음 달">›</button></div><div class="calendar-grid">${['월','화','수','목','금','토','일'].map(x=>`<small>${x}</small>`).join('')}${'<span></span>'.repeat(offset)}${Array.from({length:total},(_,i)=>{const value=month+'-'+String(i+1).padStart(2,'0');return `<button data-date="${value}" class="${date===value?'selected':''} ${data.schedule.some(e=>e.date===value)?'has-event':''}">${i+1}</button>`}).join('')}</div><h3 class="native-title">${date} 이후 일정</h3>${data.schedule.filter(e=>e.date>=date).map(e=>`<a class="calendar-event" ${e.url?'':'data-local-event'} href="${esc(e.url||'#')}" target="_blank" rel="noopener noreferrer"><time>${e.date.slice(5).replace('-','.')}</time><div><b>${esc(e.title)}</b><small>${esc(e.detail)}</small></div></a>`).join('')}`,'calendar-native')}
function bindNative(){document.querySelectorAll('[data-rank-tab]').forEach(b=>b.onclick=()=>{state.rankTab=b.dataset.rankTab;render()});
 document.querySelectorAll('[data-track]').forEach(b=>b.onclick=()=>{state.spotifyTrack=b.dataset.track;render()});
 document.querySelector('[data-spotify-home]')?.addEventListener('click',()=>{state.spotifyTrack=data.favoriteTrack.id;render()});
 document.querySelector('[data-spotify-library]')?.addEventListener('click',()=>document.querySelector('.spotify-playlist-cover')?.scrollIntoView({behavior:'smooth'}));
 document.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{state.sub='note:'+b.dataset.note;render()});
 document.querySelectorAll('[data-photo]').forEach(b=>b.onclick=()=>{state.app='photos';state.sub='photo:'+b.dataset.photo;render()});
 document.querySelector('#useWallpaper')?.addEventListener('click',()=>{data.wallImage=albumItems()[Number(state.sub.split(':')[1])].src;save();state.socialViewer=null;state.app=null;state.sub=null;render()});
 document.querySelector('[data-pet-photo]')?.addEventListener('click',()=>{state.app='photos';state.sub='photo:'+albumItems().findIndex(x=>x.src===data.petImage);render()});
 document.querySelector('#photoUpload')?.addEventListener('change',async e=>{for(const file of Array.from(e.target.files||[]).slice(0,8)){if(!file.type.startsWith('image/'))continue;const src=await new Promise(resolve=>{const reader=new FileReader;reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file)});const compressed=await new Promise(resolve=>{const img=new Image;img.onload=()=>{const scale=Math.min(1,1400/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=img.width*scale;canvas.height=img.height*scale;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.85))};img.onerror=()=>resolve(src);img.src=src});data.userPhotos??=[];data.userPhotos.unshift({src:compressed,title:file.name,album:state.sub==='album:food'?'food':state.sub==='album:sea'?'sea':undefined});}save();render()});
 document.querySelectorAll('[data-discord-friend]').forEach(b=>b.onclick=()=>{state.discordFriend=Number(b.dataset.discordFriend);state.sub='discordChat';render()});

 document.querySelector('#voiceClose')?.addEventListener('click',()=>{state.sub=null;render()});

 document.querySelector('#discordComposer')?.addEventListener('submit',e=>{e.preventDefault();const text=document.querySelector('#discordMessage').value.trim();if(!text)return;const i=state.discordFriend||0;state.discordMessages??={};state.discordMessages[i]??=[];state.discordMessages[i].push(text);render()});
 document.querySelector('#popComposer')?.addEventListener('submit',e=>{e.preventDefault();const text=document.querySelector('#popMessage').value.trim();if(!text)return;data.popItems??=[];data.popItems.push({side:'out',text,time:now()});data.popDraft='';state.popToBottom=true;save();render();const area=document.querySelector('.pop-thread');if(area)area.scrollTop=area.scrollHeight});
 document.querySelector('#popDraft')?.addEventListener('click',()=>document.querySelector('#popMessage')?.focus());
 document.querySelector('#popPhoto')?.addEventListener('click',()=>{state.popPhotos=!state.popPhotos;state.stickerOpen=false;render()});
 document.querySelectorAll('[data-x-like]').forEach(b=>b.onclick=()=>{b.classList.toggle('liked');b.setAttribute('aria-pressed',String(b.classList.contains('liked')))});
 document.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{state.calendarDate=b.dataset.date;render()});
 document.querySelectorAll('[data-month]').forEach(b=>b.onclick=()=>{const d=new Date((state.calendarDate||dateKey())+'T12:00:00');d.setDate(1);d.setMonth(d.getMonth()+Number(b.dataset.month));state.calendarDate=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-01';render()});
}
function imageRegion(src,x,y,w,h,cls='',label=''){return `<svg class="image-region ${cls}" viewBox="${x} ${y} ${w} ${h}" role="img" aria-label="${esc(label)}" preserveAspectRatio="xMidYMid slice"><image href="${esc(src)}" width="709" height="1536"/></svg>`}
function stickerImage(col=0,row=0){return imageRegion('assets/stickers-ui.jpeg',17+col*177,1000+row*117,143,113,'pop-sprite-sticker','스티커')}
