function riotInfo(bottom){return `<section class="appview riot-view riot-info-view"><header class="riot-community-head"><button class="backbtn riot-exit" aria-label="홈">‹</button><h2>정보</h2><button id="riotSettings" class="riot-round" aria-label="설정">⚙</button></header><div class="riot-community-scroll"><div class="riot-profile-art"></div><div class="riot-own-profile">${imageRegion('assets/opgg-ui.jpeg',38,246,40,40,'riot-profile-emblem','프로필 아이콘')}<h2>${esc(data.riotId.split('#')[0])} <span>#${esc(data.riotId.split('#')[1])}</span></h2><p>Riot Mobile</p><button id="riotStatus">✎　상태 설정</button>${state.editStatus?'<form id="riotStatusForm"><input id="riotStatusInput" placeholder="상태 메시지" maxlength="80"><button>저장</button></form>':''}${state.ownStatus?`<p>${esc(state.ownStatus)}</p>`:''}</div><h3>리그 오브 레전드</h3><div class="riot-game-cards">${data.recentMatches.slice(0,2).map((x,i)=>`<button data-open="rank">${imageRegion('assets/opgg-ui.jpeg',26,1012+i*219,78,78,'riot-game-art',x.name)}<b class="${x.win?'won':'lost'}">${x.win?'승리':'패배'}</b><strong>${x.name}</strong><small>개인/2인 랭크 게임</small></button>`).join('')}</div></div>${bottom}</section>`}
function instagramComposer(){const items=albumItems(),selected=items[state.igSelected||0];return `<section class="appview native instagram-native"><header class="instagram-head"><button id="igComposeCancel" aria-label="닫기">×</button><b>${state.igCompose==='caption'?'새 게시물':'최근 항목'}</b><button id="igComposeNext">${state.igCompose==='caption'?'임시 저장':'다음'}</button></header><div class="native-scroll"><img class="ig-compose-preview" src="${esc(selected?.src||'')}" alt="선택한 사진">${state.igCompose==='caption'?`<textarea id="igCaptionDraft" class="ig-caption-draft" placeholder="문구를 입력하세요…">${esc(state.igDraft?.caption||'')}</textarea>`:`<div class="ig-grid">${items.map((p,i)=>`<button data-ig-select="${i}" class="${i===(state.igSelected||0)?'ig-selected':''}" aria-label="사진 ${i+1} 선택"><img src="${esc(p.src)}" alt="${esc(p.title)}"></button>`).join('')}</div>`}</div></section>`}
function instagramProfile(){if(state.igExplore)return exploreApp();if(state.igCompose)return instagramComposer();const p=data.instagram,items=p.items||[],post=items[state.igPost],slide=state.igSlide||0;return `<section class="appview native instagram-native"><header class="instagram-head"><button class="backbtn">‹</button><b>${p.handle} ${data.key==='doran'?'<i>✓</i>':''}</b><button id="igMore" aria-label="프로필 메뉴">☰</button></header><div class="native-scroll instagram-scroll"><div class="ig-profile-top">${data.key==='peyz'?'<span class="ig-default-avatar" aria-label="기본 프로필 사진"><i></i></span>':profileAvatar('large')}<div><strong>${esc(p.name)}</strong><div class="ig-counts"><span><b>${p.posts}</b>게시물</span><span><b>${p.followers}</b>팔로워</span><span><b>${p.following}</b>팔로잉</span></div></div></div><p class="ig-bio">${esc(p.bio).replaceAll('\n','<br>')}</p><div class="ig-profile-actions"><button id="igEdit">프로필 편집</button><a href="https://www.instagram.com/${p.handle}/" target="_blank" rel="noopener noreferrer">프로필 공유</a></div><nav class="ig-tabs"><button data-ig-tab="grid" class="${!state.igTagged?'active':''}" aria-label="게시물">▦</button><button data-ig-tab="tagged" class="${state.igTagged?'active':''}" aria-label="태그됨">♙</button></nav>${state.igTagged?'':`<div class="ig-grid">${items.map((post,i)=>`<button class="ig-tile" data-ig-post="${i}" aria-label="게시물 ${i+1}"><img src="${esc(post.images[0])}" alt="${esc(post.caption||'게시물 사진')}" loading="lazy">${post.images.length>1?'<span class="ig-stack">▣</span>':''}</button>`).join('')}</div>`}</div><nav class="ig-bottom"><button data-ig-home aria-label="홈">⌂</button>${data.key==='peyz'?'<button id="igExplore" aria-label="검색 및 추천">⌕</button>':''}<a href="https://www.instagram.com/${p.handle}/" target="_blank" rel="noopener noreferrer" aria-label="프로필">◎</a><button id="igCompose" aria-label="사진 추가">⊞</button></nav>${post?`<div class="ig-post-overlay"><header><button id="igPostClose" aria-label="닫기">‹</button><b>${p.handle}</b><a href="${post.url}" target="_blank" rel="noopener noreferrer">•••</a></header><div class="ig-detail-scroll"><div class="ig-post-image"><button class="ig-expand" data-social-photo="ig:${state.igPost}:${Math.min(slide,post.images.length-1)}"><img src="${esc(post.images[Math.min(slide,post.images.length-1)])}" alt="${esc(post.caption||'게시물 사진')}"></button>${post.images.length>1?`<span class="ig-page-count">${Math.min(slide,post.images.length-1)+1}/${post.images.length}</span><button class="ig-prev" data-ig-step="-1" aria-label="이전 사진">‹</button><button class="ig-next" data-ig-step="1" aria-label="다음 사진">›</button>`:''}</div><div class="ig-post-actions"><button id="igLike" aria-label="좋아요">♡</button><a href="${post.url}" target="_blank" rel="noopener noreferrer">Instagram에서 열기 ↗</a></div><div class="ig-caption">${post.likes?`<b>좋아요 ${post.likes.toLocaleString()}개</b>`:''}<p><strong>${p.handle}</strong> ${esc(post.caption).replaceAll('\n','<br>')}</p><time>${esc(post.date||'')}</time></div></div></div>`:''}</section>`}

function stickerPicker(){return `<section class="pop-picker"><p>${data.key==='doran'?'DORAN':'어차피 우승은 페이즈'} <button id="stickerClose" aria-label="닫기">⌄</button></p><div class="pop-sticker-grid">${Array.from({length:12},(_,i)=>`<button data-sticker="${i%4},${Math.floor(i/4)}" aria-label="스티커 ${i+1}">${stickerImage(i%4,Math.floor(i/4))}</button>`).join('')}</div><div class="sticker-pack-bar"><b>＋</b><span>${data.key==='doran'?'대황란':'페이즈'}</span><span>☆</span><span>♧</span><span>•••</span></div></section>`}
