function popMediaView(){const media=state.popMedia;return `<section class="appview native pop-media-view"><header><button class="backbtn" aria-label="채팅으로">‹</button><div><b>${data.key==='doran'?'최현준임':'Peyz'}</b>${media==='jeju'?'<small>2026.10.04 14:02</small>':''}</div></header><div class="pop-full-photo">${popMediaImage(media)}</div></section>`}

