const lockSvg={lock:'<svg viewBox="0 0 24 28"><rect x="4" y="12" width="16" height="13" rx="3"/><path d="M7 12V8a5 5 0 0 1 10 0v4" fill="none" stroke="currentColor" stroke-width="2.5"/></svg>',flash:'<svg viewBox="0 0 24 30"><path d="M6 3h12v7l-4 6v11h-4V16l-4-6z" fill="none" stroke="currentColor" stroke-width="2"/><path d="M6 6h12M7 10h10" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="12" cy="19" r="1.5"/></svg>',camera:'<svg viewBox="0 0 28 24"><path d="M3 6h5l2-3h8l2 3h5v15H3z"/><circle cx="14" cy="13" r="5" fill="none" stroke="var(--camera-hole,#555)" stroke-width="2"/></svg>'};
function systemStatus(){return `<div class="status"><span>${state.locked?'':now()}</span><span class="status-right"><svg class="signal-icon" viewBox="0 0 25 18" aria-label="신호"><rect x="1" y="11" width="4" height="7" rx="1"/><rect x="7" y="8" width="4" height="10" rx="1"/><rect x="13" y="4" width="4" height="14" rx="1"/><rect x="19" y="0" width="4" height="18" rx="1"/></svg><b>5G</b><span class="battery-icon">80<i></i></span></span></div>`}
function lockView(){const pin=state.sub==='pin',digits=state.pin||'';return `<section class="lock ios-lock ${pin?'pin-open':''}" aria-label="잠금 화면"><span class="lock-symbol">${lockSvg.lock}</span>${pin?`<div class="ios-pin-panel"><form id="pinForm"><label for="pinInput">암호 입력</label><input id="pinInput" class="pin-native-input" type="password" inputmode="numeric" maxlength="4" value="${digits}" aria-label="4자리 암호" autocomplete="off"><div class="pin-dots ${state.pinError?'shake':''}" aria-label="${digits.length}자리 입력">${[0,1,2,3].map(i=>`<i class="${i<digits.length?'filled':''}"></i>`).join('')}</div><p id="pinError" role="alert">${state.pinError?'암호를 확인해 주세요':''}</p><button type="submit" hidden>잠금 해제</button></form><div id="pinPad" class="ios-pin-pad" tabindex="0">${[['1',''],['2','ABC'],['3','DEF'],['4','GHI'],['5','JKL'],['6','MNO'],['7','PQRS'],['8','TUV'],['9','WXYZ']].map(([n,t])=>`<button type="button" data-pin="${n}"><strong>${n}</strong><small>${t}</small></button>`).join('')}<span></span><button type="button" data-pin="0"><strong>0</strong></button><span></span></div><div class="ios-pin-actions"><button id="pinCancel">취소</button><button id="pinDelete">지우기</button></div></div>`:`<p class="ios-lock-date">${today()}</p><strong class="ios-lock-time">${now()}</strong><div class="lock-controls"><button id="lockFlashlight" class="${state.flashlight?'flash-on':''}" aria-label="손전등">${lockSvg.flash}</button><button id="lockOpenCamera" aria-label="카메라">${lockSvg.camera}</button></div><button id="unlock" class="ios-swipe-hint">위로 쓸어올려서 잠금 해제</button>`}${state.cameraPreview?`<div class="lock-camera-preview"><img src="${state.cameraPreview}" alt="카메라 사진"><button id="lockCameraClose">완료</button></div>`:''}</section>`}
function bindLock(){
 const startPin=()=>{state.sub='pin';state.pin='';state.pinError=false;render();document.querySelector('#pinPad')?.focus()};
 document.querySelector('#unlock')?.addEventListener('click',startPin);
 document.querySelectorAll('[data-pin]').forEach(b=>b.onclick=()=>{if((state.pin||'').length>=4)return;state.pin=(state.pin||'')+b.dataset.pin;state.pinError=false;render();if(state.pin.length===4)document.querySelector('#pinForm')?.requestSubmit()});
 document.querySelector('#pinDelete')?.addEventListener('click',()=>{state.pin=(state.pin||'').slice(0,-1);render()});
 document.querySelector('#pinCancel')?.addEventListener('click',()=>{state.sub=null;state.pin='';state.pinError=false;render()});
 document.querySelector('#pinPad')?.addEventListener('keydown',e=>{if(/^\d$/.test(e.key)){e.preventDefault();state.pin=(state.pin||'')+e.key;render();document.querySelector('#pinPad')?.focus();if(state.pin.length===4)document.querySelector('#pinForm')?.requestSubmit()}else if(e.key==='Backspace'){state.pin=(state.pin||'').slice(0,-1);render();document.querySelector('#pinPad')?.focus()}});
 document.querySelector('#lockFlashlight')?.addEventListener('click',()=>{state.flashlight=!state.flashlight;render()});
 document.querySelector('#lockCameraInput')?.addEventListener('change',e=>{const file=e.target.files[0];if(!file)return;const reader=new FileReader;reader.onload=()=>{state.cameraPreview=reader.result;render()};reader.readAsDataURL(file)});
 document.querySelector('#lockCameraClose')?.addEventListener('click',()=>{state.cameraPreview=null;render()});
}


const appMemory={},viewScroll=new Map();let lastRoute='',lastApp=null;
function routeKey(){return [state.app||'home',state.sub||'',state.app==='riot'?state.riotPage||'community':'',state.sub==='riotChat'?state.riotFriend||0:''].join('|')}
function scrollNodes(){return document.querySelectorAll('.appview .native-scroll,.appview .riot-community-scroll,.appview .riot-chat-scroll,.appview .x-layout-scroll,.appview .chat-messages,.appview .riot-conversation,.appview .appbody')}
function captureView(){if(lastRoute){viewScroll.set(lastRoute,Array.from(scrollNodes(),n=>n.scrollTop));}}
function restoreView(){const route=routeKey(),positions=viewScroll.get(route);scrollNodes().forEach((n,i)=>{if(positions)n.scrollTop=positions[i]||0;else if(n.classList.contains('pop-thread'))n.scrollTop=n.scrollHeight;});if(state.app)appMemory[state.app]=state.sub;if(lastApp!==state.app&&!state.locked&&!(typeof matchMedia==='function'&&matchMedia('(prefers-reduced-motion: reduce)').matches)){const n=document.querySelector(state.app?'.appview':'.home');if(n&&typeof n.animate==='function')n.animate([{opacity:.25,transform:'scale(.95)'},{opacity:1,transform:'scale(1)'}],{duration:220,easing:'cubic-bezier(.2,.8,.2,1)'});}lastApp=state.app;lastRoute=route;if(state.popToBottom){const n=document.querySelector('.pop-thread');if(n)n.scrollTop=n.scrollHeight;state.popToBottom=false;}}
function popRows(){return [...(data.popHistory||[]),...(data.popMessages||[]).filter(x=>x.text!=='한국은 화요일이다요'),...(data.popItems||[])].filter(x=>x.side!=='in')}
function popSearchPanel(){const dates=popRows().filter(x=>x.type==='date');return `<section class="pop-search-panel"><div><input id="popQuery" placeholder="대화 내용 검색" aria-label="대화 내용 검색"><button id="popSearchPrev" aria-label="이전 검색 결과">↑</button><button id="popSearchNext" aria-label="다음 검색 결과">↓</button><output id="popSearchCount"></output></div><select id="popJump" aria-label="날짜로 이동"><option value="">날짜로 이동</option>${dates.map(x=>`<option>${esc(x.text)}</option>`).join('')}</select></section>`}
function movePhoto(step){const n=albumItems().length;if(!n)return;const index=Number(state.sub.split(':')[1]);state.sub='photo:'+((index+step+n)%n);render()}
function bindExperience(){
 document.querySelectorAll('[data-photo-filter]').forEach(b=>b.onclick=()=>{state.onlyFavorites=b.dataset.photoFilter==='favorites';render()});
 document.querySelectorAll('[data-photo-step]').forEach(b=>b.onclick=()=>movePhoto(Number(b.dataset.photoStep)));
 document.querySelector('#favoritePhoto')?.addEventListener('click',()=>{const src=albumItems()[Number(state.sub.split(':')[1])].src;data.photoFavorites??=[];data.photoFavorites=data.photoFavorites.includes(src)?data.photoFavorites.filter(x=>x!==src):[...data.photoFavorites,src];save();render()});
 const stage=document.querySelector('#photoStage');let x,y;
 stage?.addEventListener('pointerdown',e=>{x=e.clientX;y=e.clientY});stage?.addEventListener('pointerup',e=>{if(Math.abs(e.clientX-x)>50&&Math.abs(e.clientX-x)>Math.abs(e.clientY-y)*1.5)movePhoto(e.clientX<x?1:-1)});
 document.querySelector('#popMessage')?.addEventListener('input',e=>{data.popDraft=e.target.value;save()});
 document.querySelector('#popSearchToggle')?.addEventListener('click',()=>{state.popSearching=!state.popSearching;render();document.querySelector('#popQuery')?.focus()});
 let matches=[],active=-1;const showMatch=step=>{if(!matches.length)return;active=(active+step+matches.length)%matches.length;document.querySelectorAll('.pop-search-hit').forEach(n=>n.classList.remove('pop-search-hit'));matches[active].classList.add('pop-search-hit');matches[active].scrollIntoView({block:'center',behavior:'smooth'});const count=document.querySelector('#popSearchCount');if(count)count.textContent=`${active+1}/${matches.length}`};
 document.querySelector('#popQuery')?.addEventListener('input',e=>{const query=e.target.value.trim().toLocaleLowerCase();document.querySelectorAll('.pop-search-hit').forEach(n=>n.classList.remove('pop-search-hit'));matches=query?Array.from(document.querySelectorAll('.pop-thread .pop-bubble')).filter(n=>n.textContent.toLocaleLowerCase().includes(query)):[];active=-1;const count=document.querySelector('#popSearchCount');if(count)count.textContent=query?`${matches.length}개`:'';showMatch(1)});
 document.querySelector('#popSearchPrev')?.addEventListener('click',()=>showMatch(-1));document.querySelector('#popSearchNext')?.addEventListener('click',()=>showMatch(1));
 document.querySelector('#popJump')?.addEventListener('change',e=>{Array.from(document.querySelectorAll('[data-pop-day]')).find(n=>n.dataset.popDay===e.target.value)?.scrollIntoView({block:'start',behavior:'smooth'})});
}


function socialMediaGrid(post,index){const images=post.images||[];return images.length?`<div class="x-media-grid count-${Math.min(images.length,4)}">${images.slice(0,4).map((src,i)=>`<button data-social-photo="x:${index}:${i}" aria-label="사진 ${i+1} 확대"><img src="${esc(src)}" alt="게시물 사진 ${i+1}" loading="lazy"></button>`).join('')}</div>`:''}
function socialViewer(){const v=state.socialViewer;if(!v)return '';const post=v.kind==='ig'?data.instagram.items[v.post]:data.xPosts[v.post],images=post?.images||[];if(!images.length)return '';return `<section class="social-viewer"><header><button id="socialClose" aria-label="사진 닫기">×</button><span>${v.index+1} / ${images.length}</span><a href="${esc(post.url)}" target="_blank" rel="noopener noreferrer" aria-label="원문 열기">↗</a></header><div id="socialPhotoStage"><img src="${esc(images[v.index])}" alt="게시물 원본 사진"></div><footer><button data-social-step="-1" aria-label="이전 사진">‹</button><button data-social-step="1" aria-label="다음 사진">›</button></footer></section>`}
function socialStep(step){const v=state.socialViewer,post=v.kind==='ig'?data.instagram.items[v.post]:data.xPosts[v.post];v.index=(v.index+step+post.images.length)%post.images.length;render()}
function bindSocial(){
 document.querySelectorAll('[data-photo-album]').forEach(b=>b.onclick=()=>{state.app='photos';state.sub=b.dataset.photoAlbum==='all'?null:'album:'+b.dataset.photoAlbum;render()});
 document.querySelectorAll('[data-social-photo]').forEach(b=>b.onclick=()=>{const[k,p,i]=b.dataset.socialPhoto.split(':');state.socialViewer={kind:k,post:Number(p),index:Number(i)};render()});
 document.querySelector('#socialClose')?.addEventListener('click',()=>{state.socialViewer=null;render()});
 document.querySelectorAll('[data-social-step]').forEach(b=>b.onclick=()=>socialStep(Number(b.dataset.socialStep)));
 document.querySelectorAll('[data-ig-step]').forEach(b=>b.onclick=()=>{const images=data.instagram.items[state.igPost].images;state.igSlide=((state.igSlide||0)+Number(b.dataset.igStep)+images.length)%images.length;render()});
 let startX,startY;const stage=document.querySelector('#socialPhotoStage');stage?.addEventListener('pointerdown',e=>{startX=e.clientX;startY=e.clientY});stage?.addEventListener('pointerup',e=>{if(Math.abs(e.clientX-startX)>50&&Math.abs(e.clientX-startX)>Math.abs(e.clientY-startY)*1.5)socialStep(e.clientX<startX?1:-1)});
}

function appView(){if(!state.app)return '';return ({riot,rank,discord,spotify,pop:()=>feed('pop'),xapp:()=>feed('x'),photos,notes,calendar,instagram,youtube:videoApp,clock:clockApp,soop:()=>streamApp('soop'),chzzk:()=>streamApp('chzzk'),weather:weatherApp,telephone:phoneApp,messages:messagesApp,camera:cameraApp,safari:safariApp,kakaotalk:kakaotalkApp,football:footballApp,chatgpt:gptApp,maps:mapsApp})[state.app]()}function render(){trackNativeRoute();if(!state.locked&&state.pendingNotification){openFinalNotification(state.pendingNotification);state.pendingNotification=null}document.title=`${data.name}의 iPhone`;pageTitle.textContent=`${data.name}의 iPhone`;captureView();phoneMount.innerHTML=`<article class="phone-wrap"><div class="phone-label"><strong>${esc(data.name)}의 iPhone</strong><span>${esc(data.role)}</span></div><div class="phone" style="--wall:${data.wall};--wall-image:${data.wallImage?`url('${data.wallImage}')`:'none'}"><div class="screen ${!state.locked&&['xapp','instagram','photos','soop','safari','telephone','messages','kakaotalk','chatgpt','discord','maps'].includes(state.app)?'light-app':''} ${state.notificationOpen?'notification-open':''}">${systemStatus()}<button class="notification-pull" id="notificationPull" aria-label="알림 센터 열기"></button><div class="island"></div>${state.locked||state.app?'':home()}${state.locked?lockView():''}${state.locked?(state.cameraFromLock&&state.app==='camera'?cameraApp():''):appView()}${!state.locked?socialViewer():''}${notificationCenter()}${notificationBanner()}${!state.locked&&state.app&&!state.notificationOpen?'<div class="edge-back-zone" id="edgeBackZone" aria-hidden="true"></div>':''}<div class="home-gesture-pad" id="homeGesturePad" aria-hidden="true"></div><button class="homebar"></button></div></div></article>`;bind();restoreView();bindExperience();bindSocial();bindExtra();bindHomePages();bindNativePhone();bindShellFix();bindFinalScope();bindSocialReference();bindMaps();bindKakaoApp();bindEveryday();bindRecommendations()}
function bind(){bindLock();
 const lock=document.querySelector('.lock'),bar=document.querySelector('.homebar');
 let downY;
 lock?.addEventListener('pointerdown',e=>{downY=e.clientY});
 lock?.addEventListener('pointerup',e=>{if(state.locked&&downY-e.clientY>40){state.sub='pin';render()}});
 bar?.addEventListener('pointerdown',e=>{downY=e.clientY});
 bar?.addEventListener('pointerup',e=>{if(downY-e.clientY>30)nativeHome()});
 bindAdded();bindRiot();bindNative();bindSocialApps();document.querySelector('#pinForm')?.addEventListener('submit',e=>{e.preventDefault();if(document.querySelector('#pinInput').value==='1205'){state.locked=false;state.sub=null;render()}else{state.pin='';state.pinError=true;render()}});document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{state.locked=false;state.socialViewer=null;state.libraryFolder=undefined;state.app=b.dataset.open;state.sub=appMemory[state.app]||null;state.stickerOpen=false;state.popPhotos=false;render()});document.querySelector('.homebar').onclick=nativeHome;document.querySelector('.backbtn')?.addEventListener('click',nativeBack);document.querySelector('.open-riot')?.addEventListener('click',()=>{state.sub='riotChat';render()});document.querySelector('#play')?.addEventListener('click',()=>{state.playing=!state.playing;render()})}
function fill(){lockQuote.value=data.quote;riotId.value=data.riotId;discordName.value=data.discordName;customNote.value=data.note;wallColor.value=data.wall}function close(){editor.classList.remove('open');scrim.hidden=true}editBtn.onclick=()=>{fill();editor.classList.add('open');scrim.hidden=false};closeEditor.onclick=close;scrim.onclick=close;wallImage.onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader;r.onload=()=>{data.wallImage=r.result;toast('배경 사진을 불러왔습니다')};r.readAsDataURL(f)};removeImage.onclick=()=>{delete data.wallImage;toast('배경 사진을 제거했습니다')};saveEditor.onclick=()=>{data.quote=lockQuote.value;data.riotId=riotId.value;data.discordName=discordName.value;data.note=customNote.value;data.wall=wallColor.value;save();close();render();toast('저장했습니다')};exportBtn.onclick=()=>{const b=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`${data.key}-iphone-backup.json`;a.click();URL.revokeObjectURL(a.href)};importInput.onchange=e=>{const r=new FileReader;r.onload=()=>{try{data=Object.assign({},base,JSON.parse(r.result));save();render();toast('백업을 불러왔습니다')}catch{toast('파일을 확인해 주세요')}};r.readAsText(e.target.files[0])};render();

let visibleDateKey=dateKey();function refreshPhoneDay(){const next=dateKey();if(next===visibleDateKey)return;visibleDateKey=next;applyAuthenticIcons();if(!state.app||state.app==='calendar'||state.notificationOpen)render()}
if(typeof setInterval==='function')setInterval(()=>{refreshPhoneDay();const clock=document.querySelector('.ios-lock-time'),date=document.querySelector('.ios-lock-date'),status=document.querySelector('.status>span:first-child');if(clock)clock.textContent=now();if(date)date.textContent=today();if(status)status.textContent=state.locked?'':now();const noticeClock=document.querySelector('.notification-clock strong'),noticeDate=document.querySelector('.notification-clock p');if(noticeClock)noticeClock.textContent=now();if(noticeDate)noticeDate.textContent=today()},1000);

if(typeof setInterval==='function')setInterval(tickUtilities,100);
